{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { createParser } from './parser.js'
import { createEvaluator } from './evaluator.js'
import { formatOutput } from './output.js'

// Check arguments
if (process.argv.length !== 3 || !['values', 'deps'].includes(process.argv[2])) {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const mode = process.argv[2]

// Read input
let input = ''
process.stdin.setEncoding('utf8')
process.stdin.on('data', (chunk) => { input += chunk })
process.stdin.on('end', () => {
  try {
    const parser = createParser()
    const cells = parser.parse(input)

    if (mode === 'values') {
      const evaluator = createEvaluator(cells)
      const result = evaluator.evaluateAll()
      process.stdout.write(formatOutput.values(result))
    } else {
      const evaluator = createEvaluator(cells)
      const deps = evaluator.getDependencies()
      process.stdout.write(formatOutput.deps(deps))
    }

    process.exit(0)
  } catch (error) {
    if (error.isSheetError) {
      process.stderr.write(error.message + '\n')
      process.exit(2)
    }
    throw error
  }
})
"}

