{"file_path":"src/parser.js","content":"/**
 * Parser for cell definitions from input
 */

function isValidAddress(address) {
  // Columns: A-Z (single) or AA-ZZ (double)
  // Rows: 1-999
  const match = address.match(/^([A-Z]{1,2})(\d{1,3})$/)
  if (!match) return false

  const col = match[1]
  const row = parseInt(match[2], 10)

  // Row must be at least 1
  if (row < 1) return false

  // Validate column range
  if (col.length === 1) {
    // A-Z is always valid
    return true
  } else {
    // AA-ZZ
    if (col < 'AA' || col > 'ZZ') return false
    return true
  }
}

function addressToCoords(address) {
  const match = address.match(/^([A-Z]{1,2})(\d{1,3})$/)
  const col = match[1]
  const row = parseInt(match[2], 10)

  let colNum
  if (col.length === 1) {
    colNum = col.charCodeAt(0) - 'A'.charCodeAt(0)
  } else {
    colNum = 26 + (col.charCodeAt(0) - 'A'.charCodeAt(0)) * 26 + (col.charCodeAt(1) - 'A'.charCodeAt(0))
  }

  return { col: colNum, row }
}

function makeSheetError(lineNum, message) {
  const error = new Error(message)
  error.isSheetError = true
  error.message = `error: line ${lineNum}: ${message}`
  return error
}

export function createParser() {
  return {
    parse(input) {
      const cells = new Map() // Map<address, { formula or literal }>
      const declaredAddresses = new Set()

      const lines = input.split('\n')
      // Remove trailing empty line if input ends with newline
      if (lines.length > 0 && lines[lines.length - 1] === '') {
        lines.pop()
      }

      for (let lineNum = 1; lineNum <= lines.length; lineNum++) {
        let line = lines[lineNum - 1]

        // Strip leading spaces and tabs
        const stripped = line.replace(/^[ \t]+/, '')

        // Ignore empty lines and comments
        if (stripped === '' || stripped.startsWith('#')) {
          continue
        }

        // Parse: address is run of non-space/tab, then skip one run of space/tab, then rest is content
        const parts = stripped.split(/[ \t]+/, 2)
        const address = parts[0].toUpperCase()
        const content = parts.length > 1 ? stripped.substring(parts[0].length).replace(/^[ \t]+/, '') : ''

        // Validate address
        if (!isValidAddress(address)) {
          throw makeSheetError(lineNum, `invalid cell address ${address}`)
        }

        // Check for duplicate declaration
        if (declaredAddresses.has(address)) {
          throw makeSheetError(lineNum, `cell ${address} is declared twice`)
        }
        declaredAddresses.add(address)

        // Store the cell
        cells.set(address, {
          address,
          content,
          coords: addressToCoords(address)
        })
      }

      return cells
    }
  }
}
"}

