const ERROR_TOKENS = new Set(['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!'])

function isError(value) {
  return typeof value === 'string' && ERROR_TOKENS.has(value)
}

function isNumber(value) {
  return typeof value === 'number'
}

function isBoolean(value) {
  return typeof value === 'boolean'
}

function isText(value) {
  return typeof value === 'string' && !isError(value)
}

function toNumber(value) {
  if (isNumber(value)) return value
  if (isBoolean(value)) return value ? 1 : 0
  if (isText(value)) return '#VALUE!'
  if (isError(value)) return value
  return 0
}

function compareValues(a, b) {
  // Compare following the rules:
  // - numbers compared numerically
  // - texts compared by code point
  // - booleans with false below true
  // - numbers < texts < booleans

  const getType = (v) => {
    if (isNumber(v)) return 0
    if (isText(v)) return 1
    if (isBoolean(v)) return 2
    return 3
  }

  const typeA = getType(a)
  const typeB = getType(b)

  if (typeA !== typeB) return typeA - typeB

  if (isNumber(a) && isNumber(b)) return a < b ? -1 : a > b ? 1 : 0
  if (isText(a) && isText(b)) return a < b ? -1 : a > b ? 1 : 0
  if (isBoolean(a) && isBoolean(b)) return (a ? 1 : 0) - (b ? 1 : 0)

  return 0
}

class Tokenizer {
  constructor(formula) {
    this.formula = formula
    this.pos = 0
  }

  skipWhitespace() {
    while (this.pos < this.formula.length && /[ \t]/.test(this.formula[this.pos])) {
      this.pos++
    }
  }

  peek() {
    this.skipWhitespace()
    return this.formula[this.pos]
  }

  peekChar(n = 0) {
    return this.formula[this.pos + n]
  }

  next() {
    this.skipWhitespace()
    const ch = this.formula[this.pos]
    if (ch) this.pos++
    return ch
  }

  nextToken() {
    this.skipWhitespace()

    if (this.pos >= this.formula.length) return null

    const ch = this.formula[this.pos]

    // Operators and parentheses
    if ('()^*+-/<>='.includes(ch)) {
      this.pos++
      // Handle <> and <=, >=
      if (ch === '<' || ch === '>') {
        if (this.peekChar(-1 + 1) === '=') {
          this.pos++
          return ch + '='
        }
        if (ch === '<' && this.peekChar(-1 + 1) === '>') {
          this.pos++
          return '<>'
        }
      }
      if (ch === '=' && this.peekChar(-1 + 1) === '=') {
        this.pos++
        return '=='
      }
      return ch
    }

    // Numbers
    if (/\d/.test(ch) || (ch === '.' && /\d/.test(this.peekChar(1)))) {
      let numStr = ''
      while (this.pos < this.formula.length && /[\d.]/.test(this.formula[this.pos])) {
        numStr += this.formula[this.pos]
        this.pos++
      }
      return { type: 'NUMBER', value: parseFloat(numStr) }
    }

    // Words (identifiers, cell addresses, functions)
    if (/[A-Za-z]/.test(ch)) {
      let word = ''
      while (this.pos < this.formula.length && /[A-Za-z0-9]/.test(this.formula[this.pos])) {
        word += this.formula[this.pos]
        this.pos++
      }
      word = word.toUpperCase()

      // Check if it's a boolean or function
      if (word === 'TRUE') return { type: 'BOOLEAN', value: true }
      if (word === 'FALSE') return { type: 'BOOLEAN', value: false }
      if (['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'].includes(word)) {
        return { type: 'FUNCTION', value: word }
      }

      // It's a cell address or unknown function name
      return { type: 'IDENTIFIER', value: word }
    }

    return null
  }
