    return '#ERR!'
  }

  parseArgument() {
    const expr = this.parseFormula()

    // Check for range
    if (this.currentToken === ':') {
      this.currentToken = this.tokenizer.nextToken()
      const end = this.parseFormula()
      return { type: 'RANGE', start: expr, end }
    }

    return expr
  }
}

